sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
	if (isLoading || newValue === '' || g_form.getValue("day")==="") {
		return;
	}
	g_form.clearMessages();
	var gaValidateDuplicate = new GlideAjax("AjaxUtils");
	gaValidateDuplicate.addParam("sysparm_name","valDuplicate");
	var course_id = g_form.getValue("course");
	var date = g_form.getValue("day");
	var dateParts = date.split("/"); 
	var selectedDate = new Date(dateParts[2], dateParts[1] - 1, dateParts[0]);
	var today = new Date();
	today.setHours(0, 0, 0, 0);
	if (selectedDate <= today) {
		g_form.addErrorMessage("Invalid date");
		g_form.setValue("day","");
		g_form.setValue("course",'');
		return;
	}
	gaValidateDuplicate.addParam("sysparam_course_sys_id",course_id);
	gaValidateDuplicate.addParam("sysparam_date",date);
	gaValidateDuplicate.getXML(callback);
	//Type appropriate comment here, and begin script below

}

function callback(response){
	var answer = response.responseXML.documentElement.getAttribute("answer");
	if(answer=='true'){
		g_form.setValue("course","");
		g_form.setValue("day","");
		g_form.addErrorMessage("Duplicate Training");
	}
}
